"""Detached cycle snapshots and bounded asynchronous JSONL recording.

Only the writer thread serializes and writes samples/events. Metadata and
source snapshots are created before servo enable; close runs after disable.
An SDK send success means acceptance by the adapter, not physical execution.
"""
from __future__ import annotations

from dataclasses import asdict, is_dataclass
from datetime import datetime, timezone
import hashlib
import json
import math
from pathlib import Path
import platform
from queue import Empty, Full, Queue
import subprocess
from threading import Thread
import time

import numpy as np

SCHEMA_VERSION = 1


def json_value(value):
    """Keep invalid sensor values representable as JSON null, never NaN tokens."""
    if isinstance(value, np.ndarray):
        return json_value(value.tolist())
    if isinstance(value, np.generic):
        return json_value(value.item())
    if isinstance(value, float) and not math.isfinite(value):
        return None
    if isinstance(value, Path):
        return str(value)
    if is_dataclass(value):
        return json_value(asdict(value))
    if isinstance(value, dict):
        return {str(key): json_value(item) for key, item in value.items()}
    if isinstance(value, (list, tuple, set)):
        return [json_value(item) for item in value]
    return value


def pose_snapshot(pose):
    if pose is None:
        return None
    return {"frame_id": pose.frame_id, "position_m": pose.position_m.copy(),
            "quaternion_wxyz": pose.quaternion_wxyz.copy()}


def admittance_snapshot(app):
    if app.motion is None:
        return None
    state = app.motion.state()
    return {"frame_id": state.frame_id, "offset": state.offset.copy(),
            "velocity": state.velocity.copy(),
            "enabled_axes": app.motion.enabled_axes.copy(),
            "nominal_pose": pose_snapshot(app.motion.nominal_pose)}


def capture_stage(capture, method, app, *args):
    """Observation failures must never interrupt the hardware command path."""
    if capture is None:
        return
    try:
        getattr(capture, method)(*args)
    except Exception as exc:
        capture.data.setdefault("observer_errors", []).append(str(exc))
        app._observer_error(exc)


class CycleCapture:
    """One control tick; stages share a sequence but retain their own timestamps."""
    def __init__(self, app, sequence, elapsed_s, dt_s):
        self.data = {
            "schema_version": SCHEMA_VERSION, "sequence": sequence,
            "elapsed_s": elapsed_s, "dt_s": dt_s,
            "tick_start_monotonic_ns": time.perf_counter_ns(),
            "pressed_before": sorted(app.keys.pressed),
            "admittance_before": admittance_snapshot(app),
            "fault_before": app.servo.fault,
            "admittance_updated": False, "command_sent": False,
        }

    def feedback(self, app, state, measured):
        self.data.update({
            "feedback_received_monotonic_ns": time.perf_counter_ns(),
            "joint_names": list(measured.names),
            "measured_q_rad": measured.position_rad.copy(),
            "measured_qd_rad_s": state.joint_velocity_rad_s.copy(),
            "measured_joint_torque": state.joint_torque.copy(),
            "sdk_cartesian_pose_raw": state.cartesian_pose.copy(),
            "raw_sensor_wrench": state.torque_sensor.copy(),
            "raw_sensor_frame_id": app.sensor_frame_id,
            "measured_tcp_pose": pose_snapshot(app.kinematics.forward(measured)),
        })

    def jog(self, jog):
        self.data["jog"] = {"base_frame": jog.base_frame,
                            "linear_m_s": jog.linear_m_s.copy(),
                            "angular_rad_s": jog.angular_rad_s.copy()}

    def reference(self, app, wrench):
        self.data["admittance_updated"] = True
        self.data["admittance_integrated"] = admittance_snapshot(app)
        self.data["unclamped_pose"] = pose_snapshot(app.motion.corrected_pose)
        self.data["corrected_pose"] = pose_snapshot(app.last_corrected_pose)
        self.data["admittance_input_wrench"] = (
            wrench.as_vector() * app.motion.enabled_axes
        )
        before = self.data["admittance_before"]
        if before is None:
            raise ValueError("missing pre-update admittance snapshot")
        after = self.data["admittance_integrated"]
        cfg = app.admittance.config
        v = before["velocity"]
        x = before["offset"]
        unbounded = v + self.data["dt_s"] * (
            self.data["admittance_input_wrench"] - cfg.damping*v - cfg.stiffness*x
        ) / cfg.mass
        self.data["velocity_clipped_axes"] = np.abs(unbounded) > cfg.max_velocity
        self.data["translation_offset_clamped"] = (
            np.linalg.norm(after["offset"][:3]) > app.args.adm_max_offset_m
        )
        self.data["rotation_offset_clamped"] = (
            np.linalg.norm(after["offset"][3:]) > np.deg2rad(app.args.adm_max_offset_deg)
        )

    def finish(self, app, error=None):
        self.data.update({
            "tick_end_monotonic_ns": time.perf_counter_ns(),
            "status": app.status, "fault": app.servo.fault,
            "dry_run": bool(app.args.dry_run), "error": error,
            "pressed_after": sorted(app.keys.pressed),
            "admittance_after": admittance_snapshot(app),
        })
        return self.data


class AsyncRecorder:
    """Opt-in recorder. Dropped rows and writer errors are explicit in summary."""
    def __init__(self, directory, metadata, *, queue_size=4096):
        if queue_size < 1:
            raise ValueError("log queue size must be positive")
        self.directory = Path(directory).expanduser().resolve()
        self.directory.mkdir(parents=True, exist_ok=False)
        self.queue = Queue(maxsize=queue_size)
        self.accepted = self.written = self.dropped = 0
        self.written_samples = self.observer_errors = 0
        self.error = None
        self.closed = False
        self._files = {}
        try:
            for name in ("samples", "events"):
                self._files[name] = (self.directory / f"{name}.jsonl").open("x", encoding="utf-8")
            (self.directory / "metadata.json").write_text(
                json.dumps(json_value(metadata), ensure_ascii=False, indent=2, allow_nan=False),
                encoding="utf-8",
            )
        except Exception:
            for file in self._files.values():
                file.close()
            raise
        self._thread = Thread(target=self._run, name="jaka-log-writer", daemon=True)
        self._thread.start()

    def publish(self, kind, record):
        # Caller transfers a detached snapshot; never enqueue live controller arrays.
        if self.closed or self.error:
            self.dropped += 1
            return False
        try:
            self.queue.put_nowait((kind, record))
        except Full:
            self.dropped += 1
            return False
        self.accepted += 1
        return True

    def note_observer_error(self):
        # A failed snapshot can lose even the first/last cycle without a visible gap.
        self.observer_errors += 1

    def _run(self):
        last_flush = time.monotonic()
        try:
            while True:
                try:
                    item = self.queue.get(timeout=0.2)
                except Empty:
                    for file in self._files.values():
                        file.flush()
                    continue
                try:
                    if item is None:
                        break
                    kind, record = item
                    self._files[kind].write(json.dumps(
                        json_value(record), ensure_ascii=False,
                        separators=(",", ":"), allow_nan=False,
                    ) + "\n")
                    self.written += 1
                    if kind == "samples":
                        self.written_samples += 1
                    if time.monotonic() - last_flush >= 0.5:
                        for file in self._files.values():
                            file.flush()
                        last_flush = time.monotonic()
                finally:
                    self.queue.task_done()
        except Exception as exc:
            self.error = f"{type(exc).__name__}: {exc}"
        finally:
            for file in self._files.values():
                try:
                    file.close()
                except Exception as exc:
                    self.error = self.error or str(exc)

    def close(self, timeout_s=5.0):
        if self.closed:
            return
        self.closed = True
        deadline = time.monotonic() + timeout_s
        if self._thread.is_alive():
            try:
                self.queue.put(None, timeout=max(0.0, deadline-time.monotonic()))
            except Full:
                self.error = self.error or "writer queue did not drain on close"
            self._thread.join(max(0.0, deadline-time.monotonic()))
        summary = {
            "accepted": self.accepted, "written": self.written,
            "dropped": self.dropped, "pending": max(0, self.accepted-self.written),
            "written_samples": self.written_samples, "observer_errors": self.observer_errors,
            "writer_error": self.error, "writer_stopped": not self._thread.is_alive(),
        }
        summary["complete"] = (
            summary["writer_stopped"] and not summary["writer_error"]
            and not summary["dropped"] and not summary["pending"]
            and not summary["observer_errors"]
        )
        (self.directory / "summary.json").write_text(
            json.dumps(summary, indent=2), encoding="utf-8",
        )


def session_metadata(args, app, project_root):
    """Snapshot effective parameters and exact model/calibration/code sources."""
    from replace_disk_robot.kinematics.jaka import PROJECT_JAKA_URDF
    from replace_disk_robot.control import admittance, admittance_motion, servo
    from replace_disk_robot.contact import force_processing
    sources = {}
    paths = [Path(args.config), PROJECT_JAKA_URDF, Path(__file__),
             Path(__file__).with_name("node.py"), Path(__file__).with_name("reference.py"),
             Path(__file__).with_name("wrench.py"), Path(__file__).with_name("config.py"),
             Path(__file__).with_name("frontend.py"),
             Path(admittance.__file__), Path(admittance_motion.__file__),
             Path(servo.__file__), Path(force_processing.__file__)]
    if getattr(args, "gravity_json", None):
        paths.append(Path(args.gravity_json))
    for path in paths:
        if path.is_file():
            content = path.read_bytes()
            sources[str(path.resolve())] = {
                "sha256": hashlib.sha256(content).hexdigest(),
                "content": content.decode("utf-8"),
            }
    try:
        revision = subprocess.run(["git", "rev-parse", "HEAD"], cwd=project_root,
                                  capture_output=True, text=True, timeout=2).stdout.strip()
        dirty = bool(subprocess.run(["git", "status", "--porcelain"], cwd=project_root,
                                   capture_output=True, text=True, timeout=2).stdout.strip())
    except (OSError, subprocess.TimeoutExpired):
        revision, dirty = None, None
    return {
        "schema_version": SCHEMA_VERSION,
        "created_utc": datetime.now(timezone.utc).isoformat(),
        "clock": {"monotonic_ns": time.perf_counter_ns(), "unix_ns": time.time_ns(),
                  "sensor_timestamp_available": False},
        "python_version": platform.python_version(), "numpy_version": np.__version__,
        "git_revision": revision, "git_dirty": dirty,
        "effective_args": vars(args), "sources": sources,
        "base_frame": app.base_frame, "tool_frame": app.tool_frame,
        "kinematics_class": f"{type(app.kinematics).__module__}.{type(app.kinematics).__qualname__}",
        "joint_names": list(app.kinematics.joint_names),
        "sensor_frame": app.sensor_frame_id,
        "sensor_to_tool_rotation": app.sensor_to_tool_rotation.copy(),
        "tool_to_sensor_m": app.tool_to_sensor_m.copy(),
        "servo_config": app.servo.config,
        "runtime_calibration": {
            "adapter_bias_sensor": app.ft.bias.copy(),
            "gravity_bias_sensor": (None if app.gravity_compensator is None
                                    else app.gravity_compensator.bias_sensor.copy()),
            "gravity_compensation_config": (None if app.gravity_compensator is None
                                            else app.gravity_compensator.config),
        },
        "units": {"position": "m", "angle": "rad", "force": "N", "torque": "N*m",
                  "offset_axes": ["x", "y", "z", "rx", "ry", "rz"],
                  "quaternion": "wxyz", "sdk_cartesian_pose_raw": "mm,rad",
                  "measured_joint_torque": "SDK raw units"},
    }

"""Single-loop JAKA keyboard node: assembly, lifecycle and command dispatch."""
from __future__ import annotations
import argparse
import sys
import time
from copy import deepcopy
from collections.abc import Callable
import numpy as np
from replace_disk_robot.adapters.jaka import JakaError, JakaRobotAdapter, fmt_array
from replace_disk_robot.adapters.jaka.session import RateLoop, edg_session, make_client
from replace_disk_robot.control import CartesianServo, ServoConfig
from replace_disk_robot.core import JointState, Pose, Wrench
from replace_disk_robot.kinematics.jaka import JakaKinematics
from replace_disk_robot.safety import ForceLimitGuard
from .config import PROJECT_ROOT, _parse_args, _validate_admittance_args
from .wrench import WrenchPipeline
from .reference import ReferencePipeline
from .log import AsyncRecorder, CycleCapture, capture_stage, session_metadata


_RECOVERABLE_FAULTS = {
    None,
    "focus_lost",
    "stopped",
    "command_timeout",
    "force_limit",
    "tracking_error",
    "loop_timeout",
    "invalid_dt",
    "invalid_wrench",
}
_FORCE_RESUME_RATIO = 0.8

SampleCallback = Callable[[float, object, JointState, object, "JakaKeyboardServo"], None]

class JakaKeyboardServo:
    """Own the hardware lifecycle and preserve one ordered command path."""
    def __init__(self, client, args, *, sample_callback=None, kinematics=None,
                 recorder=None, tick_callback=None):
        self.client, self.args = client, args
        self.kinematics = JakaKinematics() if kinematics is None else kinematics
        self.arm = JakaRobotAdapter(client, joint_names=self.kinematics.joint_names)
        self.base_frame = self.kinematics.base_frame
        self.tool_frame = self.kinematics.end_effector_frame
        self.command_frame = self.tool_frame if args.command_frame == "tool" else self.base_frame
        self.servo = CartesianServo(
            self.kinematics,
            self.kinematics.joint_limits_rad,
            ServoConfig(
                linear_speed_m_s=args.linear_speed,
                angular_speed_rad_s=np.deg2rad(args.angular_speed_deg),
                max_tracking_error_rad=args.max_joint_error_rad,
            ),
        )
        self.guard = ForceLimitGuard(
            force_limit_n=args.max_force_n,
            torque_limit_nm=args.max_torque_nm,
        )
        self.sample_callback = sample_callback

        self.wrench = WrenchPipeline(client, args, self.kinematics)
        self.reference = ReferencePipeline(args, self.kinematics, self.arm, self.servo)
        self.admittance_enabled = bool(args.admittance)
        self.recorder, self.tick_callback = recorder, tick_callback

        self.last_wrench = None
        self.servo_enabled = False
        self.status = "initializing"
        self._next_print = 0.0
        self._last_now = None
        self._closed = False
        self._tick_sequence = 0
        self._active_capture = None
        self._observer_error_reported = False

    @property
    def ft(self):
        return self.wrench.ft

    @property
    def sensor_frame_id(self):
        return self.wrench.sensor_frame_id

    @property
    def sensor_to_tool_rotation(self):
        return self.wrench.sensor_to_tool_rotation

    @property
    def tool_to_sensor_m(self):
        return self.wrench.tool_to_sensor_m

    @property
    def gravity_compensator(self):
        return self.wrench.gravity_compensator

    @property
    def wrench_processor(self):
        return self.wrench.wrench_processor

    @property
    def payload_mass_kg(self):
        return self.wrench.payload_mass_kg

    @property
    def payload_com_sensor_m(self):
        return self.wrench.payload_com_sensor_m

    @property
    def keys(self):
        return self.reference.keys

    @property
    def motion(self):
        return self.reference.motion

    @property
    def admittance(self):
        return self.reference.admittance

    @property
    def motion_config(self):
        return self.reference.motion_config

    @property
    def last_external_wrench(self):
        return self.reference.last_external_wrench

    @last_external_wrench.setter
    def last_external_wrench(self, value):
        self.reference.last_external_wrench = value

    @property
    def last_corrected_pose(self):
        return self.reference.last_corrected_pose

    @last_corrected_pose.setter
    def last_corrected_pose(self, value):
        self.reference.last_corrected_pose = value

    def _configure_gravity_compensation(self):
        return self.wrench._configure_gravity_compensation()

    def _sensor_pose_in_base(self, measured):
        return self.wrench._sensor_pose_in_base(measured)

    def _tare_compensated_wrench(self, state, measured):
        return self.wrench._tare_compensated_wrench(state, measured)

    def _read_wrench(self, state, measured):
        return self.wrench._read_wrench(state, measured)

    def _gravity_compensated_wrench(self, state, measured):
        return self.wrench._gravity_compensated_wrench(state, measured)

    def _reset_compliance(self, measured):
        reset = self.reference._reset_compliance(measured)
        if reset and self.wrench_processor is not None:
            self.wrench_processor.reset()
        if reset:
            self._record_event("reference_reset")

    def _update_compliance(self, jog, wrench, tcp_pose, dt_s):
        return self.reference._update_compliance(jog, wrench, tcp_pose, dt_s)

    def _clamp_offset(self, corrected, nominal):
        return self.reference._clamp_offset(corrected, nominal)

    def _jog_to_servo(self, reference=None):
        return self.reference._jog_to_servo(reference)

    def admittance_text(self):
        return self.reference.admittance_text()

    def initialize(self) -> None:
        state0 = self.client.read_edg_state()
        q0 = JointState(self.arm.joint_names, state0.joint_position_rad)
        print(
            f"[keyboard] initial q={fmt_array(q0.position_rad, 4)} "
            f"base={self.base_frame} command_frame={self.command_frame}"
        )

        gravity_json = getattr(self.args, "gravity_json", None)
        use_gravity = bool(gravity_json) and getattr(
            self.args, "gravity_compensation_enable", True
        )
        if use_gravity:
            self._configure_gravity_compensation()
            if getattr(self.args, "tare_compensated", False):
                self._tare_compensated_wrench(state0, q0)
        else:
            if getattr(self.args, "tare_compensated", False):
                raise ValueError(
                    "--tare-compensated requires gravity compensation; "
                    "set --gravity-compensation-enable true"
                )
            if getattr(self.args, "tare_enable", True):
                print(f"[keyboard] taring FT with {self.args.tare_samples} samples")
                bias = self.ft.tare(
                    samples=self.args.tare_samples,
                    period_s=self.args.tare_period_ms / 1000.0,
                )
                print(f"[keyboard] FT bias={fmt_array(bias, 4)}")

        self.last_wrench = self._read_wrench(state0, q0)
        if self.admittance_enabled:
            print(
                "[keyboard] admittance: axes="
                f"{'translation' if self.args.admittance_axes == 'translation' else 'all'}, "
                f"offset limit={self.args.adm_max_offset_m * 1000.0:g} mm / "
                f"{self.args.adm_max_offset_deg:g} deg"
            )
            self._print_compliance_seed(q0, state0)

        if self.recorder is None and getattr(self.args, "log_dir", None) is not None:
            self.recorder = AsyncRecorder(
                self.args.log_dir, session_metadata(self.args, self, PROJECT_ROOT),
                queue_size=getattr(self.args, "log_queue_size", 4096),
            )
        self._record_event("initialized", dry_run=self.args.dry_run)
        if self.args.dry_run:
            self.servo.reset(q0)
            self.status = "dry_run"
            print("[keyboard] dry-run: servo not enabled, no motion commands sent")
            return

        self.client.servo_move_enable(True)
        self.servo_enabled = True
        print("[keyboard] servo_move_enable(True)")

        # The robot can settle slightly when servo mode is entered.  Reset the
        # hold target from the post-enable measured state.
        state_servo = self.client.read_edg_state()
        q_servo = JointState(self.arm.joint_names, state_servo.joint_position_rad)
        self.servo.reset(q_servo)
        self.last_wrench = self._read_wrench(state_servo, q_servo)
        self._print_compliance_seed(q_servo, state_servo)
        self.status = "holding"

    def _print_compliance_seed(self, measured: JointState, state) -> None:
        """Print the external wrench and offset at a freshly seeded reference."""

        if not self.admittance_enabled:
            return
        self._reset_compliance(measured)
        try:
            wrench = self._read_wrench(state, measured)
        except (ValueError, RuntimeError):
            return
        self.last_wrench = wrench
        self.last_external_wrench = wrench
        print(f"[keyboard] admittance reference: {self.admittance_text()}")

    def shutdown(self) -> None:
        if self._closed:
            return
        self._closed = True
        self.keys.clear()
        if self.servo_enabled:
            try:
                self.client.servo_move_enable(False)
                print("[keyboard] servo_move_enable(False)")
            except Exception as exc:  # noqa: BLE001 - best-effort stop
                print(f"[keyboard] servo-disable warning: {exc}", file=sys.stderr)
            finally:
                self.servo_enabled = False
        self._record_event("shutdown")
        if self.recorder is not None:
            try:
                self.recorder.close()
            except Exception as exc:
                self._observer_error(exc)

    def stop(self, reason: str, measured: JointState | None = None) -> None:
        self._record_event("stop", reason=reason)
        self.keys.clear()
        if measured is None:
            try:
                measured = self.arm.read_joint_state()
            except Exception:  # noqa: BLE001 - still record fault
                measured = None

        if measured is not None:
            self.servo.halt(measured, reason)
            if self.servo_enabled and not self.args.dry_run:
                try:
                    self._send_joint_positions(measured)
                except Exception as exc:  # noqa: BLE001 - best-effort hold
                    print(f"[keyboard] hold-command warning: {exc}", file=sys.stderr)
        self._reset_compliance(measured)
        self.status = reason

    def resume(self) -> bool:
        """Resume a recoverable stop from fresh, verified robot feedback.

        Enter never clears a force stop while the load is still close to the
        trip threshold.  Resetting the Cartesian target to the current measured
        joints prevents replaying the target that existed before the fault.
        """

        self._record_event("resume_requested", fault=self.servo.fault)
        self.keys.clear()
        fault = self.servo.fault
        if self.args.dry_run:
            print("[keyboard] resume ignored in dry-run")
            return False
        if fault not in _RECOVERABLE_FAULTS:
            print(f"[keyboard] {fault} is not recoverable with Enter; restart after inspection")
            return False

        try:
            state = self.client.read_edg_state()
            measured = JointState(self.arm.joint_names, state.joint_position_rad)
            wrench = self._read_wrench(state, measured)
        except Exception as exc:  # noqa: BLE001 - stay stopped on bad feedback
            print(f"[keyboard] resume denied: feedback unavailable: {exc}", file=sys.stderr)
            return False

        wrench_vector = wrench.as_vector()
        if not np.isfinite(wrench_vector).all():
            print("[keyboard] resume denied: wrench is not finite", file=sys.stderr)
            return False
        force = float(np.linalg.norm(wrench.force_n))
        torque = float(np.linalg.norm(wrench.torque_nm))
        force_resume_limit = _FORCE_RESUME_RATIO * self.args.max_force_n
        torque_resume_limit = _FORCE_RESUME_RATIO * self.args.max_torque_nm
        if force > force_resume_limit or torque > torque_resume_limit:
            print(
                "[keyboard] resume denied: release the load first; "
                f"|F|={force:.3f} N (need <= {force_resume_limit:.3f}), "
                f"|T|={torque:.3f} Nm (need <= {torque_resume_limit:.3f})",
                file=sys.stderr,
            )
            return False

        try:
            self.servo.reset(measured)
        except (ValueError, RuntimeError) as exc:
            print(f"[keyboard] resume denied: invalid joint state: {exc}", file=sys.stderr)
            return False
        self.last_wrench = wrench
        self.status = "holding"
        print(
            f"[keyboard] resumed from measured pose after {fault or 'hold'}; "
            f"|F|={force:.3f} N |T|={torque:.3f} Nm"
        )
        self._record_event("resumed", previous_fault=fault)
        return True

    def handle_focus(self, focused: bool) -> None:
        self._record_event("focus", focused=focused)
        self.keys.clear()
        if not focused and self.servo.fault is None:
            self.stop("focus_lost")
            print("[keyboard] focus lost: holding measured pose")
        elif focused and self.servo.fault == "focus_lost":
            self.resume()

    def _status_text(self) -> str:
        if self.servo.fault:
            if self.servo.fault == "force_limit":
                return "force_limit: release load, then press Enter"
            if self.servo.fault in _RECOVERABLE_FAULTS:
                return f"{self.servo.fault}: press Enter to re-anchor and resume"
            return f"{self.servo.fault}: restart script after inspection"
        return self.status

    def _observer_error(self, exc):
        try:
            if self.recorder is not None:
                self.recorder.note_observer_error()
        except Exception:
            pass
        if not self._observer_error_reported:
            self._observer_error_reported = True
            print(f"[log] observer failed; control continues: {exc}", file=sys.stderr)

    def _record_event(self, event, **fields):
        if self.recorder is None:
            return
        try:
            self.recorder.publish("events", {
                "event": event, "sequence": self._tick_sequence,
                "monotonic_ns": time.perf_counter_ns(), **fields,
            })
        except Exception as exc:
            self._observer_error(exc)

    def record_input_event(self, key, action):
        self._record_event("key", key=key, action=action)

    def _send_joint_positions(self, command):
        attempt = None
        if self._active_capture is not None:
            attempt = {"q_rad": command.position_rad.copy(),
                       "start_monotonic_ns": time.perf_counter_ns(), "accepted": False}
            self._active_capture.data.setdefault("send_attempts", []).append(attempt)
        try:
            self.arm.command_joint_positions(command)
        except Exception as exc:
            if attempt is not None:
                attempt["error"] = f"{type(exc).__name__}: {exc}"
            self._record_event("command_rejected", error=str(exc))
            raise
        else:
            if attempt is not None:
                attempt["accepted"] = True
                self._active_capture.data["command_sent"] = True
        finally:
            if attempt is not None:
                attempt["end_monotonic_ns"] = time.perf_counter_ns()
        self._record_event("command_accepted", q_rad=command.position_rad.copy())

    def tick(self, elapsed_s: float, dt_s: float) -> None:
        capture = None
        self._tick_sequence += 1
        self.wrench.capture_stages = self.recorder is not None or self.tick_callback is not None
        if self.wrench.capture_stages:
            try:
                capture = CycleCapture(self, self._tick_sequence, elapsed_s, dt_s)
            except Exception as exc:
                self._observer_error(exc)
        self._active_capture = capture
        error = None
        try:
            self._tick(elapsed_s, dt_s, capture)
        except BaseException as exc:
            error = f"{type(exc).__name__}: {exc}"
            raise
        finally:
            self._active_capture = None
            if capture is not None:
                try:
                    record = capture.finish(self, error)
                    if self.recorder is not None:
                        self.recorder.publish("samples", record)
                        if getattr(self.recorder, "error", None):
                            self._observer_error(self.recorder.error)
                    if self.tick_callback is not None:
                        self.tick_callback(deepcopy(record))
                except Exception as exc:
                    self._observer_error(exc)

    def _tick(self, elapsed_s: float, dt_s: float, capture=None) -> None:
        if capture is not None:
            capture.data["feedback_read_start_monotonic_ns"] = time.perf_counter_ns()
        state = self.client.read_edg_state()
        measured = JointState(self.arm.joint_names, state.joint_position_rad)
        capture_stage(capture, "feedback", self, self, state, measured)
        try:
            wrench = self._read_wrench(state, measured)
        except (ValueError, RuntimeError) as exc:
            self.stop("invalid_wrench", measured)
            print(f"[keyboard] invalid wrench: {exc}", file=sys.stderr)
            return
        self.last_wrench = wrench
        if capture is not None:
            capture.data["wrench_stages"] = deepcopy(self.wrench.stages)

        # Optional instrumentation hook used by data-collection tools.  The
        # callback receives the same EDG packet that drives this control tick,
        # so joint state, raw F/T data and robot pose remain synchronized.
        if self.sample_callback is not None:
            self.sample_callback(elapsed_s, state, measured, wrench, self)

        if not np.isfinite(dt_s) or dt_s <= 0:
            self.stop("invalid_dt", measured)
            return
        if dt_s > self.servo.config.max_dt_s:
            self.stop("loop_timeout", measured)
            return

        jog = self._jog_to_servo(
            self.motion.nominal_pose if self.motion is not None else None
        )
        capture_stage(capture, "jog", self, jog)
        if self.args.dry_run:
            # Still integrate the compliance chain so the printed offset and
            # the sign of the external force can be verified before enabling
            # Servo; no command is submitted in dry-run.
            if self.admittance_enabled and self.servo.fault is None:
                self._update_compliance(
                    jog, wrench, self.kinematics.forward(measured), dt_s
                )
                capture_stage(capture, "reference", self, self, wrench)
                self.last_external_wrench = wrench
            self.status = "dry_run"
            self._print_line(elapsed_s, measured, measured.position_rad, wrench)
            return

        if self.admittance_enabled:
            self.last_external_wrench = wrench
            # A latched fault must not let the integrator wind up; the offset is
            # re-seeded from the measured pose on resume.
            if self.servo.fault is None:
                corrected = self._update_compliance(
                    jog, wrench, self.kinematics.forward(measured), dt_s
                )
                capture_stage(capture, "reference", self, self, wrench)
                self.servo.submit_pose(corrected, elapsed_s)
        else:
            self.servo.submit(jog, elapsed_s)
        try:
            target = self.servo.update(measured, dt_s, elapsed_s)
        except (ValueError, RuntimeError) as exc:
            self.stop("servo_error", measured)
            print(f"[keyboard] servo error: {exc}", file=sys.stderr)
            return

        safe_q, tripped = self.guard.filter_arm_target(
            wrench.as_vector(),
            measured.position_rad,
            target.position_rad,
        )
        if capture is not None:
            capture.data["servo_target_q_rad"] = target.position_rad.copy()
            capture.data["force_gate_tripped"] = bool(tripped)
        if tripped:
            self.stop("force_limit", measured)
            safe_q = measured.position_rad
        else:
            self.status = self.servo.status

        if capture is not None:
            capture.data["final_command_q_rad"] = np.asarray(safe_q).copy()
        self._send_joint_positions(
            JointState(self.arm.joint_names, safe_q)
        )
        self._print_line(elapsed_s, measured, safe_q, wrench)

    def _print_line(self, elapsed_s, measured, command_q, wrench) -> None:
        if elapsed_s < self._next_print:
            return
        self._next_print += 0.5
        force = float(np.linalg.norm(wrench.force_n))
        torque = float(np.linalg.norm(wrench.torque_nm))
        admittance = self.admittance_text()
        print(
            f"[keyboard] t={elapsed_s:6.3f}s "
            f"q={fmt_array(measured.position_rad, 4)} "
            f"cmd={fmt_array(command_q, 4)} "
            f"|F|={force:6.3f}N |T|={torque:6.3f}Nm "
            + (f"{admittance} " if admittance else "")
            + f"{self._status_text()}"
        )


def _run_headless(app: JakaKeyboardServo) -> None:
    loop = RateLoop(app.args.rate_hz)
    last_now = None
    for elapsed_s, now in loop:
        dt_s = 1.0 / app.args.rate_hz if last_now is None else now - last_now
        last_now = now
        app.tick(elapsed_s, dt_s)
        if elapsed_s >= app.args.seconds:
            break


def main() -> None:
    args = _parse_args()
    if args.rate_hz <= 0:
        raise SystemExit("--rate-hz must be positive")
    if args.seconds < 0:
        raise SystemExit("--seconds must be non-negative")
    if args.headless and args.seconds <= 0:
        raise SystemExit("--headless requires --seconds > 0")
    _validate_admittance_args(args)

    client = make_client(args)
    app = None
    try:
        with edg_session(client, torque_sensor_mode=args.torque_sensor_mode) as client:
            app = JakaKeyboardServo(client, args)
            try:
                app.initialize()
                if args.headless:
                    _run_headless(app)
                else:
                    from .frontend import _run_window
                    _run_window(app)
            finally:
                app.shutdown()
    except KeyboardInterrupt:
        print("\n[keyboard] interrupted by user")
    except (JakaError, RuntimeError, ValueError) as exc:
        print(f"[keyboard] FAILED: {exc}", file=sys.stderr)
        raise SystemExit(1) from exc
    finally:
        if app is not None:
            app.shutdown()

"""Keyboard/reference composition using the existing control algorithms."""
from __future__ import annotations
import numpy as np
from replace_disk_robot.control import (
    AdmittanceConfig, AdmittanceController, CartesianJog, KeyControl,
    KeyboardAdmittanceController, MotionReferenceConfig,
)
from replace_disk_robot.core import JointState, Pose, Wrench
from replace_disk_robot.core.rotation import (
    multiply as quaternion_multiply, quaternion_from_rotation_vector,
    rotation_matrix, rotation_vector_from_matrix,
)

def _base_translation_from_keys(
    pressed: set[str],
    tool_z_in_base: np.ndarray,
    speed_m_s: float,
) -> np.ndarray:
    """Build the real-robot base-mode translation command.

    The arm mount ``jaka_base_link`` is yawed -90 degrees relative to the
    mobile platform.  Platform left/right is therefore jaka-base -X/+X.
    R/F deliberately remain on the current tool +Z insertion axis.
    """

    tool_z = np.asarray(tool_z_in_base, dtype=float).copy()
    norm = float(np.linalg.norm(tool_z))
    if tool_z.shape != (3,) or not np.isfinite(tool_z).all() or norm < 1e-12:
        raise ValueError("tool_z_in_base must be a finite non-zero 3-vector")
    tool_z /= norm

    linear = np.zeros(3)
    if "w" in pressed:
        linear += np.array([0.0, 0.0, 1.0])
    if "s" in pressed:
        linear -= np.array([0.0, 0.0, 1.0])
    if "a" in pressed:
        linear -= np.array([1.0, 0.0, 0.0])
    if "d" in pressed:
        linear += np.array([1.0, 0.0, 0.0])
    if "r" in pressed:
        linear += tool_z
    if "f" in pressed:
        linear -= tool_z
    linear /= max(1.0, float(np.linalg.norm(linear)))
    return linear * float(speed_m_s)


class ReferencePipeline:
    def __init__(self, args, kinematics, arm, servo):
        self.args, self.kinematics, self.arm, self.servo = args, kinematics, arm, servo
        self.base_frame, self.tool_frame = kinematics.base_frame, kinematics.end_effector_frame
        self.command_frame = self.tool_frame if args.command_frame == "tool" else self.base_frame
        self.keys = KeyControl(
            args.linear_speed,
            np.deg2rad(args.angular_speed_deg),
            base_frame=self.command_frame,
        )
        self.admittance_enabled = bool(args.admittance)
        self.motion: KeyboardAdmittanceController | None = None
        self.last_external_wrench: Wrench | None = None
        self.last_corrected_pose: Pose | None = None
        if self.admittance_enabled:
            self.admittance = AdmittanceController(AdmittanceConfig(
                frame_id=self.tool_frame,
                mass=args.adm_mass,
                damping=args.adm_damping,
                stiffness=args.adm_stiffness,
                max_velocity=args.adm_max_velocity,
                max_dt_s=max(0.01, 4.0 / args.rate_hz),
            ))
            enabled_axes = np.array(
                [True, True, True, False, False, False]
                if args.admittance_axes == "translation" else [True] * 6,
                dtype=bool,
            )
            axis_index = {"x": 0, "y": 1, "z": 2, "rx": 3, "ry": 4, "rz": 5}
            for axis in getattr(args, "adm_disable_axes", ()):
                enabled_axes[axis_index[axis]] = False
            self.motion_config = MotionReferenceConfig(
                enabled_axes=enabled_axes,
                max_dt_s=max(0.01, 4.0 / args.rate_hz),
            )
    def _reset_compliance(self, measured: JointState | None) -> None:
        """Re-seed nominal/admittance state at the measured pose.

        Called on start, resume and every stop so that a fault recovery never
        replays a stale compliant offset.
        """

        if not self.admittance_enabled:
            return False
        if measured is None:
            try:
                measured = self.arm.read_joint_state()
            except Exception:  # noqa: BLE001 - keep the previous reference
                return False
        pose = self.kinematics.forward(measured)
        if self.motion is None:
            self.motion = KeyboardAdmittanceController(
                self.admittance, pose, self.motion_config, tcp_frame_id=self.tool_frame,
            )
        else:
            self.motion.reset(pose)
        self.last_external_wrench = None
        self.last_corrected_pose = pose
        return True

    def _clamp_offset(self, corrected: Pose, nominal: Pose) -> Pose:
        """Limit the compliant displacement relative to the nominal pose.

        ``AdmittanceController`` intentionally has no offset clamp; on hardware
        the caller owns that limit.
        """

        delta = np.asarray(corrected.position_m, dtype=float) - np.asarray(
            nominal.position_m, dtype=float
        )
        distance = float(np.linalg.norm(delta))
        limit_m = float(self.args.adm_max_offset_m)
        position = (
            np.asarray(nominal.position_m, dtype=float) + delta * (limit_m / distance)
            if distance > limit_m else np.asarray(corrected.position_m, dtype=float)
        )

        relative = (
            rotation_matrix(corrected.quaternion_wxyz)
            @ rotation_matrix(nominal.quaternion_wxyz).T
        )
        rotation_vector = rotation_vector_from_matrix(relative)
        angle = float(np.linalg.norm(rotation_vector))
        limit_rad = float(np.deg2rad(self.args.adm_max_offset_deg))
        if angle > limit_rad:
            # Scale the *relative* rotation and apply it to the nominal pose;
            # the corrected quaternion is already nominal-composed.
            delta_quaternion = quaternion_from_rotation_vector(
                rotation_vector * (limit_rad / angle)
            )
            quaternion = quaternion_multiply(delta_quaternion, np.asarray(
                nominal.quaternion_wxyz, dtype=float
            ))
            quaternion = quaternion / np.linalg.norm(quaternion)
        else:
            quaternion = np.asarray(corrected.quaternion_wxyz, dtype=float)
        return Pose(nominal.frame_id, position, quaternion)

    def _update_compliance(self, jog, wrench, tcp_pose, dt_s) -> Pose:
        """One keyboard-nominal + admittance step; returns the clamped pose."""

        if self.motion is None:
            raise RuntimeError("admittance is enabled but the motion reference is not seeded")
        corrected = self.motion.update(jog, wrench, tcp_pose, dt_s)
        self.last_corrected_pose = self._clamp_offset(corrected, self.motion.nominal_pose)
        return self.last_corrected_pose

    def admittance_text(self) -> str:
        """Compact admittance state for the status line and window title."""

        if not self.admittance_enabled:
            return ""
        force = 0.0
        if self.last_external_wrench is not None:
            force = float(np.linalg.norm(self.last_external_wrench.force_n))
        offset = self.motion.state().offset if self.motion is not None else np.zeros(6)
        axes = self.motion.enabled_axes if self.motion is not None else np.zeros(6, dtype=bool)
        return (
            f"|Fext|={force:5.2f}N "
            f"dx={np.linalg.norm(offset[:3]) * 1000.0:4.1f}mm "
            f"dth={np.rad2deg(np.linalg.norm(offset[3:])):4.1f}deg "
            f"axes={''.join('1' if value else '0' for value in axes)}"
        )

    def _jog_to_servo(self, reference: JointState | Pose | None = None) -> CartesianJog:
        """Map keyboard keys to Servo's base-linear/intrinsic-TCP convention.

        * tool mode: W/S/A/D and rotations use the current tool0 frame.  R/F
          still follow the current tool0 +Z/-Z insertion axis.
        * base mode: W/S use base +/-Z; A/D use base -X/+X, which corresponds
          to platform left/right for the -90-degree arm mounting; R/F move
          along current tool0 +Z/-Z.  Base-axis rotations are converted to
          intrinsic TCP angular velocity.

        ``reference`` overrides the pose the keys are interpreted in; the
        admittance path passes the *nominal* pose so that compliant offsets do
        not feed back into the keyboard frame.
        """
        if reference is None:
            target = self.servo.target
            if target is None:
                target = self.arm.read_joint_state()
            pose = self.kinematics.forward(target)
        elif isinstance(reference, Pose):
            pose = reference
        else:
            pose = self.kinematics.forward(reference)
        base_from_tool = rotation_matrix(pose.quaternion_wxyz)

        if self.command_frame == self.tool_frame:
            command = self.keys.command(forward_axis=np.array([0.0, 0.0, 1.0]))
            return CartesianJog(
                self.base_frame,
                base_from_tool @ command.linear_m_s,
                command.angular_rad_s,
            )

        command = self.keys.command()
        linear = _base_translation_from_keys(
            self.keys.pressed,
            base_from_tool[:, 2],
            self.args.linear_speed,
        )
        return CartesianJog(
            self.base_frame,
            linear,
            base_from_tool.T @ command.angular_rad_s,
        )

"""Keyboard/joystick nominal pose generation combined with admittance.

The missing link between :class:`~replace_disk_robot.control.key_control.KeyControl`
and :class:`~replace_disk_robot.control.admittance.AdmittanceController` is the
nominal Cartesian pose:

* held keys integrate a nominal pose;
* releasing the keys stops the nominal pose but keeps compliance active;
* the admittance controller adds an unbounded offset to that pose.

The class is backend-neutral.  With tcp_frame_id set, callers provide the
external wrench in TCP axes and the measured TCP pose in the kinematics base
frame. The compliant offset is transformed into that base frame before Servo.
IK, collision checks, workspace limits and joint limits stay in
:class:`~replace_disk_robot.control.servo.CartesianServo`.
"""

from __future__ import annotations

from dataclasses import dataclass

import numpy as np
from numpy.typing import ArrayLike, NDArray

from ..core.ports import AdmittanceControllerPort
from ..core.rotation import (
    multiply,
    quaternion_from_rotation_vector,
    rotation_matrix,
)
from ..core.types import AdmittanceState, CartesianJog, Pose, Wrench


@dataclass(frozen=True)
class MotionReferenceConfig:
    """Axis switches and timing for compliant keyboard motion.

    ``enabled_axes`` is a six-element mask ``[x, y, z, rx, ry, rz]``. Disabled
    wrench axes are zeroed before the admittance controller, which lets the
    first deployment run translation-only compatibility while keeping keyboard
    rotation commands available.  Nominal pose and admittance offset are not
    clamped by this class.
    """

    enabled_axes: ArrayLike = (True,) * 6
    max_dt_s: float = 0.05

    def __post_init__(self) -> None:
        axes = np.asarray(self.enabled_axes, dtype=bool)
        if axes.shape != (6,):
            raise ValueError("enabled_axes must be a boolean 6-vector")
        if not np.isfinite(self.max_dt_s) or self.max_dt_s <= 0.0:
            raise ValueError("max_dt_s must be finite and positive")
        object.__setattr__(self, "enabled_axes", axes.copy())


class KeyboardAdmittanceController:
    """Generate ``nominal -> corrected`` Cartesian poses for a jog input.

    The input ``jog`` follows the historical Servo convention:

    * ``linear_m_s`` in the shared base/output frame;
    * ``angular_rad_s`` intrinsic to the *nominal TCP* axes.

    ``update`` integrates the nominal pose, masks disabled admittance axes,
    and returns the admittance-corrected pose for a pose-tracking servo.
    The caller owns any limit on nominal lead or compliant displacement.
    """

    def __init__(
        self,
        admittance: AdmittanceControllerPort,
        initial_pose: Pose,
        config: MotionReferenceConfig | None = None,
        *,
        tcp_frame_id: str | None = None,
    ) -> None:
        missing = [
            name
            for name in ("update", "reset", "state")
            if not hasattr(admittance, name)
        ]
        if missing:
            raise TypeError(
                "admittance must implement update/reset/state; "
                f"missing {missing}"
            )
        if not isinstance(initial_pose, Pose):
            raise TypeError("initial_pose must be a Pose")
        if config is not None and not isinstance(config, MotionReferenceConfig):
            raise TypeError("config must be a MotionReferenceConfig")
        self.admittance = admittance
        self.config = config or MotionReferenceConfig()
        self._frame_id = initial_pose.frame_id
        if tcp_frame_id is not None and not tcp_frame_id:
            raise ValueError("tcp_frame_id must not be empty")
        self._tcp_frame_id = tcp_frame_id
        expected_admittance_frame = tcp_frame_id or self._frame_id
        if admittance.state().frame_id != expected_admittance_frame:
            raise ValueError(
                f"admittance frame must be {expected_admittance_frame!r}"
            )
        self._nominal = initial_pose
        self._corrected = initial_pose
        self._enabled_axes = self.config.enabled_axes.copy()
        self.reset(initial_pose)

    @property
    def frame_id(self) -> str:
        return self._frame_id

    @property
    def nominal_pose(self) -> Pose:
        return self._nominal

    @property
    def corrected_pose(self) -> Pose:
        return self._corrected

    @property
    def enabled_axes(self) -> NDArray[np.bool_]:
        return self._enabled_axes.copy()

    def set_enabled_axes(self, axes: ArrayLike) -> None:
        """Replace the runtime admittance axis mask without touching state."""
        array = np.asarray(axes, dtype=bool)
        if array.shape != (6,):
            raise ValueError("enabled_axes must be a boolean 6-vector")
        self._enabled_axes = array.copy()

    def state(self) -> AdmittanceState:
        return self.admittance.state()

    def reset(self, measured_pose: Pose) -> None:
        """Reset nominal and admittance state to the measured pose."""
        self._check_frame(measured_pose, "measured_pose")
        self._nominal = measured_pose
        self._corrected = measured_pose
        self.admittance.reset(
            self._tcp_origin() if self._tcp_frame_id else measured_pose
        )

    def update(
        self,
        jog: CartesianJog,
        external_wrench: Wrench,
        measured_pose: Pose,
        dt_s: float,
    ) -> Pose:
        """Return the corrected pose for one control step."""
        if not isinstance(jog, CartesianJog):
            raise TypeError("jog must be a CartesianJog")
        if not isinstance(external_wrench, Wrench):
            raise TypeError("external_wrench must be a Wrench")
        self._check_frame(measured_pose, "measured_pose")
        if jog.base_frame != self._frame_id:
            raise ValueError(
                f"jog frame {jog.base_frame!r} does not match controller frame "
                f"{self._frame_id!r}"
            )
        wrench_frame = self._tcp_frame_id or self._frame_id
        if external_wrench.frame_id != wrench_frame:
            raise ValueError(
                f"wrench frame {external_wrench.frame_id!r} does not match "
                f"controller frame {wrench_frame!r}"
            )
        if not np.isfinite(dt_s) or dt_s <= 0.0 or dt_s > self.config.max_dt_s:
            raise ValueError(
                f"dt_s must be finite and in (0, {self.config.max_dt_s}]"
            )

        candidate = self._advance(self._nominal, jog, dt_s)
        self._nominal = candidate
        masked_wrench = self._mask_wrench(external_wrench)
        if self._tcp_frame_id:
            self.admittance.update(self._tcp_origin(), masked_wrench, dt_s)
            offset = self.admittance.state().offset
            base_from_tcp = rotation_matrix(measured_pose.quaternion_wxyz)
            position = candidate.position_m + base_from_tcp @ offset[:3]
            world_delta = quaternion_from_rotation_vector(base_from_tcp @ offset[3:])
            quaternion = multiply(world_delta, candidate.quaternion_wxyz)
            self._corrected = Pose(
                self._frame_id, position, quaternion / np.linalg.norm(quaternion)
            )
        else:
            self._corrected = self.admittance.update(candidate, masked_wrench, dt_s)
        return self._corrected

    def _tcp_origin(self) -> Pose:
        return Pose(self._tcp_frame_id, np.zeros(3), [1.0, 0.0, 0.0, 0.0])

    def _check_frame(self, pose: Pose, name: str) -> None:
        if not isinstance(pose, Pose):
            raise TypeError(f"{name} must be a Pose")
        if pose.frame_id != self._frame_id:
            raise ValueError(
                f"{name} frame {pose.frame_id!r} does not match controller "
                f"frame {self._frame_id!r}"
            )

    @staticmethod
    def _advance(nominal: Pose, jog: CartesianJog, dt_s: float) -> Pose:
        rotation = rotation_matrix(nominal.quaternion_wxyz)
        position = nominal.position_m + np.asarray(jog.linear_m_s) * dt_s
        world_angular_velocity = rotation @ np.asarray(jog.angular_rad_s)
        delta = quaternion_from_rotation_vector(world_angular_velocity * dt_s)
        quaternion = multiply(delta, nominal.quaternion_wxyz)
        quaternion = quaternion / np.linalg.norm(quaternion)
        return Pose(nominal.frame_id, position, quaternion)

    def _mask_wrench(self, wrench: Wrench) -> Wrench:
        if np.all(self._enabled_axes):
            return wrench
        value = wrench.as_vector() * self._enabled_axes
        return Wrench(wrench.frame_id, value[:3], value[3:])

"""Frame transforms, filtering and deadbands for measured wrenches.

``AdmittanceController`` deliberately requires a wrench expressed in a known
frame with the sign of an *external load*.  Raw sensors usually do neither:

* a wrist F/T sensor reports the load it applies to its child link, which is
  the opposite of the external load acting on the tool;
* the sensor frame is neither the robot base nor the controlled TCP;
* wrench readings are noisy and have a small offset drift.

This module keeps that plumbing outside the admittance model.  It contains no
MuJoCo, ROS or hardware import so it can be unit-tested with plain arrays.
"""

from __future__ import annotations

from dataclasses import dataclass

import numpy as np
from numpy.typing import ArrayLike

from ..core.rotation import rotation_matrix
from ..core.types import Pose, Wrench


def _non_negative_scalar(value: ArrayLike, name: str) -> float:
    array = np.asarray(value, dtype=float)
    if array.ndim != 0 or not np.isfinite(array) or float(array) < 0.0:
        raise ValueError(f"{name} must be a finite non-negative scalar")
    return float(array)


def _vector(value: ArrayLike, size: int, name: str) -> np.ndarray:
    array = np.asarray(value, dtype=float)
    if array.shape != (size,) or not np.all(np.isfinite(array)):
        raise ValueError(f"{name} must be a finite {size}-vector")
    return array.copy()


@dataclass(frozen=True)
class SensorCompensationConfig:
    """Raw sensor calibration with gravity expressed in the pose parent frame."""

    frame_id: str
    load_sign: float = -1.0
    gravity_frame_id: str = "world"
    gravity_m_s2: ArrayLike = (0.0, 0.0, -9.80665)
    payload_mass_kg: float = 0.0
    payload_com_sensor_m: ArrayLike = (0.0, 0.0, 0.0)

    def __post_init__(self) -> None:
        if not self.frame_id:
            raise ValueError("frame_id must not be empty")
        if self.load_sign not in (-1.0, 1.0):
            raise ValueError("load_sign must be +1 or -1")
        if not self.gravity_frame_id:
            raise ValueError("gravity_frame_id must not be empty")
        object.__setattr__(self, "gravity_m_s2", _vector(self.gravity_m_s2, 3, "gravity_m_s2"))
        object.__setattr__(self, "payload_mass_kg", _non_negative_scalar(self.payload_mass_kg, "payload_mass_kg"))
        object.__setattr__(self, "payload_com_sensor_m", _vector(self.payload_com_sensor_m, 3, "payload_com_sensor_m"))


class SensorWrenchCompensator:
    """Subtract sensor bias and predicted payload gravity in sensor axes.

    Tare requires no contact and separates static bias from the gravity
    predicted at the tare pose. A payload change requires another tare.
    """

    def __init__(self, config: SensorCompensationConfig) -> None:
        if not isinstance(config, SensorCompensationConfig):
            raise TypeError("config must be SensorCompensationConfig")
        self.config = config
        self.bias_sensor = np.zeros(6)

    def _gravity(self, sensor_pose: Pose, mass: float, com: ArrayLike) -> np.ndarray:
        gravity_sensor = rotation_matrix(sensor_pose.quaternion_wxyz).T @ self.config.gravity_m_s2
        force = self.config.load_sign * mass * gravity_sensor
        return np.r_[force, np.cross(_vector(com, 3, "payload_com_sensor_m"), force)]

    def _inputs(self, wrench: Wrench, sensor_pose: Pose, payload_mass_kg, payload_com_sensor_m):
        if wrench.frame_id != self.config.frame_id:
            raise ValueError(f"wrench frame {wrench.frame_id!r} must be {self.config.frame_id!r}")
        if sensor_pose.frame_id != self.config.gravity_frame_id:
            raise ValueError(
                f"sensor pose frame {sensor_pose.frame_id!r} must be "
                f"{self.config.gravity_frame_id!r}"
            )
        mass = self.config.payload_mass_kg if payload_mass_kg is None else _non_negative_scalar(payload_mass_kg, "payload_mass_kg")
        com = self.config.payload_com_sensor_m if payload_com_sensor_m is None else payload_com_sensor_m
        return self._gravity(sensor_pose, mass, com)

    def tare(self, wrench: Wrench, sensor_pose: Pose, *, payload_mass_kg=None, payload_com_sensor_m=None) -> None:
        predicted = self._inputs(wrench, sensor_pose, payload_mass_kg, payload_com_sensor_m)
        self.bias_sensor = wrench.as_vector() - predicted

    def compensate(self, wrench: Wrench, sensor_pose: Pose, *, payload_mass_kg=None, payload_com_sensor_m=None) -> Wrench:
        predicted = self._inputs(wrench, sensor_pose, payload_mass_kg, payload_com_sensor_m)
        corrected = wrench.as_vector() - self.bias_sensor - predicted
        return Wrench(self.config.frame_id, corrected[:3], corrected[3:])


@dataclass(frozen=True)
class WrenchProcessorConfig:
    """Configuration for :class:`WrenchProcessor`.

    ``load_sign`` converts a sensor convention into an external load:

    * ``+1``: the sensor already reads the external load acting on the tool;
    * ``-1``: the sensor reads the parent-on-child/wrist load, as MuJoCo's
      ``force``/``torque`` sensors do.

    Filtering is a first-order low-pass in the output frame.  Set
    ``filter_alpha=1.0`` to disable it.  Deadbands are applied per component
    after filtering; zero disables a deadband.
    """

    frame_id: str
    load_sign: float = -1.0
    filter_alpha: float = 0.2
    force_deadband_n: ArrayLike = 0.0
    torque_deadband_nm: ArrayLike = 0.0

    def __post_init__(self) -> None:
        if not self.frame_id:
            raise ValueError("frame_id must not be empty")
        if not np.isfinite(self.load_sign) or self.load_sign not in (-1.0, 1.0):
            raise ValueError("load_sign must be either +1 or -1")
        if not np.isfinite(self.filter_alpha) or not 0.0 < self.filter_alpha <= 1.0:
            raise ValueError("filter_alpha must be finite and in (0, 1]")
        object.__setattr__(
            self,
            "force_deadband_n",
            _non_negative_scalar(self.force_deadband_n, "force_deadband_n"),
        )
        object.__setattr__(
            self,
            "torque_deadband_nm",
            _non_negative_scalar(self.torque_deadband_nm, "torque_deadband_nm"),
        )


def external_wrench_at_point(
    wrench: Wrench,
    sensor_pose_in_frame: Pose,
    tcp_position_in_frame: ArrayLike,
    *,
    load_sign: float = -1.0,
) -> Wrench:
    """Express ``wrench`` as an external load about a TCP in one output frame.

    ``sensor_pose_in_frame`` is the pose of the sensor origin/orientation and
    ``tcp_position_in_frame`` the point about which the equivalent wrench should
    act, both in the same output frame.  The returned wrench uses the output
    frame of ``sensor_pose_in_frame``.

    The moment shift follows from static equilibrium::

        f_ext     = sign * R f_sensor
        tau_ext   = sign * (R tau_sensor + (p_sensor - p_tcp) x R f_sensor)
    """

    if not isinstance(wrench, Wrench):
        raise TypeError("wrench must be a Wrench")
    if not isinstance(sensor_pose_in_frame, Pose):
        raise TypeError("sensor_pose_in_frame must be a Pose")
    if not np.isfinite(load_sign) or load_sign not in (-1.0, 1.0):
        raise ValueError("load_sign must be either +1 or -1")

    point = np.asarray(tcp_position_in_frame, dtype=float)
    if point.shape != (3,) or not np.all(np.isfinite(point)):
        raise ValueError("tcp_position_in_frame must be a finite 3-vector")

    rotation = rotation_matrix(sensor_pose_in_frame.quaternion_wxyz)
    force = rotation @ wrench.force_n
    torque_about_sensor = rotation @ wrench.torque_nm
    lever = sensor_pose_in_frame.position_m - point
    torque = torque_about_sensor + np.cross(lever, force)
    return Wrench(
        sensor_pose_in_frame.frame_id,
        load_sign * force,
        load_sign * torque,
    )


def external_wrench_at_tcp(
    wrench: Wrench,
    sensor_pose_in_base: Pose,
    tcp_pose_in_base: Pose,
    tcp_frame_id: str,
    *,
    load_sign: float = -1.0,
) -> Wrench:
    """Shift moment to TCP origin and express force and moment in TCP axes."""
    if sensor_pose_in_base.frame_id != tcp_pose_in_base.frame_id:
        raise ValueError("sensor and TCP poses must have the same parent frame")
    if not tcp_frame_id:
        raise ValueError("tcp_frame_id must not be empty")
    in_base = external_wrench_at_point(
        wrench, sensor_pose_in_base, tcp_pose_in_base.position_m,
        load_sign=load_sign,
    )
    tcp_from_base = rotation_matrix(tcp_pose_in_base.quaternion_wxyz).T
    return Wrench(
        tcp_frame_id,
        tcp_from_base @ in_base.force_n,
        tcp_from_base @ in_base.torque_nm,
    )


class WrenchProcessor:
    """Stateful external-load filter in one explicit output frame."""

    def __init__(self, config: WrenchProcessorConfig) -> None:
        if not isinstance(config, WrenchProcessorConfig):
            raise TypeError("config must be a WrenchProcessorConfig")
        self.config = config
        self._filtered = np.zeros(6)
        self._previous_tcp_pose: Pose | None = None

    def reset(self) -> None:
        """Clear the low-pass state.  The next update seeds the filter."""
        self._filtered[:] = 0.0
        self._previous_tcp_pose = None

    def state(self) -> Wrench:
        """Return the last filtered external wrench."""
        return Wrench(
            self.config.frame_id,
            self._filtered[:3].copy(),
            self._filtered[3:].copy(),
        )

    def update(
        self,
        wrench: Wrench,
        sensor_pose_in_frame: Pose,
        tcp_position_in_frame: ArrayLike,
    ) -> Wrench:
        """Transform, filter and deadband one sensor reading."""
        if sensor_pose_in_frame.frame_id != self.config.frame_id:
            raise ValueError(
                f"sensor pose frame {sensor_pose_in_frame.frame_id!r} does not "
                f"match processor frame {self.config.frame_id!r}"
            )
        external = external_wrench_at_point(
            wrench,
            sensor_pose_in_frame,
            tcp_position_in_frame,
            load_sign=self.config.load_sign,
        )
        self._previous_tcp_pose = None
        return self._filter(external)

    def update_tcp(self, wrench: Wrench, sensor_pose_in_base: Pose, tcp_pose_in_base: Pose) -> Wrench:
        """Transform to TCP, then filter and apply deadbands in TCP axes."""
        external = external_wrench_at_tcp(
            wrench, sensor_pose_in_base, tcp_pose_in_base,
            self.config.frame_id, load_sign=self.config.load_sign,
        )
        return self._filter(external, tcp_pose_in_base)

    def _filter(self, external: Wrench, tcp_pose: Pose | None = None) -> Wrench:
        value = external.as_vector()
        previous = self._filtered.copy()
        if tcp_pose is not None and self._previous_tcp_pose is not None:
            old = self._previous_tcp_pose
            if old.frame_id != tcp_pose.frame_id:
                raise ValueError("TCP parent frame changed; reset the wrench filter")
            base_from_old = rotation_matrix(old.quaternion_wxyz)
            new_from_base = rotation_matrix(tcp_pose.quaternion_wxyz).T
            force_base = base_from_old @ previous[:3]
            moment_base = base_from_old @ previous[3:]
            moment_base += np.cross(old.position_m - tcp_pose.position_m, force_base)
            previous = np.r_[new_from_base @ force_base, new_from_base @ moment_base]
        alpha = float(self.config.filter_alpha)
        self._filtered = alpha * value + (1.0 - alpha) * previous
        self._previous_tcp_pose = tcp_pose
        output = self._filtered.copy()
        force_deadband = float(self.config.force_deadband_n)
        torque_deadband = float(self.config.torque_deadband_nm)
        if force_deadband > 0.0:
            output[:3][np.abs(output[:3]) < force_deadband] = 0.0
        if torque_deadband > 0.0:
            output[3:][np.abs(output[3:]) < torque_deadband] = 0.0
        return Wrench(self.config.frame_id, output[:3], output[3:])
